-- =========================================================
-- PRÁCTICA 3 - Parte 3: tablas de la base de datos telemedicina2026 en PostgreSQL (Supabase)
-- Traducción de las tablas de MySQL:
--   int AUTO_INCREMENT  ->  integer GENERATED BY DEFAULT AS IDENTITY
--   datetime            ->  timestamp
--   sin ENGINE, CHARSET ni comillas `...`
-- Ejecutar en Supabase: SQL Editor -> New query -> pegar -> Run
-- =========================================================

CREATE TABLE gestores (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre varchar(150) NOT NULL,
  apellidos varchar(150) NOT NULL,
  usuario varchar(150) NOT NULL,
  password varchar(150) NOT NULL
);

CREATE TABLE categorias (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre varchar(150) NOT NULL
);

CREATE TABLE ubicaciones (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre varchar(150) NOT NULL
);

CREATE TABLE areas_salud (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  codigo_postal varchar(5) NOT NULL UNIQUE,
  nombre varchar(100) NOT NULL,
  gestor integer REFERENCES gestores (id)
);

CREATE TABLE modelos (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre varchar(150) NOT NULL,
  categoria integer NOT NULL REFERENCES categorias (id),
  horas_maximas integer NOT NULL
);

CREATE TABLE recursos (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  modelo integer NOT NULL REFERENCES modelos (id),
  ubicacion integer NOT NULL REFERENCES ubicaciones (id),
  numero_serie varchar(150) NOT NULL,
  estado integer NOT NULL
);

CREATE TABLE sanitarios (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre varchar(150) NOT NULL,
  apellidos varchar(150) NOT NULL,
  usuario varchar(150) NOT NULL,
  password varchar(150) NOT NULL,
  area_salud integer REFERENCES areas_salud (id)
);

CREATE TABLE resenyas (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  recurso integer NOT NULL REFERENCES recursos (id),
  sanitario integer NOT NULL REFERENCES sanitarios (id),
  fecha timestamp NOT NULL,
  valor integer NOT NULL,
  descripcion varchar(500) NOT NULL
);

CREATE TABLE reservas (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  recurso integer NOT NULL REFERENCES recursos (id),
  sanitario integer NOT NULL REFERENCES sanitarios (id),
  horas_estimadas integer NOT NULL,
  fecha_peticion timestamp NOT NULL,
  fecha_inicio timestamp DEFAULT NULL,
  fecha_fin timestamp DEFAULT NULL
);

-- Seguridad (RLS): Supabase publica automáticamente las tablas en su API web.
-- Activando RLS sin reglas, nadie puede leerlas ni modificarlas desde esa API;
-- nuestro servidor Node se conecta directamente a la base de datos y sigue funcionando.
ALTER TABLE gestores ENABLE ROW LEVEL SECURITY;
ALTER TABLE categorias ENABLE ROW LEVEL SECURITY;
ALTER TABLE ubicaciones ENABLE ROW LEVEL SECURITY;
ALTER TABLE areas_salud ENABLE ROW LEVEL SECURITY;
ALTER TABLE modelos ENABLE ROW LEVEL SECURITY;
ALTER TABLE recursos ENABLE ROW LEVEL SECURITY;
ALTER TABLE sanitarios ENABLE ROW LEVEL SECURITY;
ALTER TABLE resenyas ENABLE ROW LEVEL SECURITY;
ALTER TABLE reservas ENABLE ROW LEVEL SECURITY;
